import { Routes } from '@angular/router';


export const routes: Routes = [
    { path: 'houses', loadChildren: (() => import('./house/house.module').then(m => m.HouseModule)) },
    { path: '', redirectTo: 'houses', pathMatch: 'full' },
    {
        path: 'login',
        loadComponent: () => import('./auth/components/login-page/login-page.component').then(m => m.LoginPageComponent)
    },
    {
        path: 'ankaList',
        loadComponent: () => import('./anka/components/anka-list/anka-list.component').then(m => m.AnkaListComponent)
    },
    { path: 'admin', loadChildren: (() => import('./admin/admin.module').then(m => m.AdminModule)) },
    { path: '**', redirectTo: 'houses', pathMatch: 'full' },
];
